<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, shallowRef } from 'vue';
import type { BiliFolderData, BiliVideoData } from '../services/bilibili.service';
import type { MyRepoItem } from '../github/my-repos-store';
import type { GitHubRawRepo } from '../services/github.service';
import type { GitHubUserList } from '../github/lists-client';
import { repositoriesInBoard, repositoryGroups } from './board-filters';
import type { ResourceAttachment } from './resource-content';
const props = defineProps<{ kind:'bilibili'|'github'; selectedResources:ResourceAttachment[]; disabled?:boolean }>();
const emit = defineEmits<{ close:[]; select:[resource:ResourceAttachment]; dragStart:[resource:ResourceAttachment]; dragEnd:[] }>();
const ready=ref(false),loading=ref(false),error=ref(''),warning=ref('');
const reposLoading=ref(false),reposError=ref(''),reposWarning=ref('');
const starsLoading=ref(false),starsError=ref(''),starsWarning=ref(''),starsLoaded=ref(false);
declare const chrome:any;
const selectedId=ref(''),folders=ref<BiliFolderData[]>([]),videos=ref<BiliVideoData[]>([]),total=ref(0),page=ref(1),hasMore=ref(false),query=ref('');
const pageSize=18;
const totalPages=computed(()=>Math.max(1,page.value+(hasMore.value?1:0),Math.ceil(total.value/pageSize)));
const repoData=shallowRef<() => {repos:MyRepoItem[];customGroups:string[];repoGroupsMap:Record<string,string[]>;loading:boolean}>(()=>({repos:[],customGroups:[],repoGroupsMap:{},loading:false}));
const starData=shallowRef<() => {repos:GitHubRawRepo[];lists:GitHubUserList[];repoListNames:Map<string,string[]>;loading:boolean}>(()=>({repos:[],lists:[],repoListNames:new Map(),loading:false}));
let generation=0,alive=true,repoRequest:AbortController|null=null,starRequest:AbortController|null=null;
function folderKey(folder:BiliFolderData){return folder.isSeason?`season:${folder.id}`:String(folder.id||folder.fid);}
const options=computed(()=>props.kind==='bilibili'?folders.value.map(folder=>({id:folderKey(folder),label:folder.title,count:folder.media_count,group:folder.isOther?'其他收藏':folder.isCollected?'收藏的合集 / 收藏夹':'我创建的收藏夹'})):[{id:'all',label:'我的全部仓库',count:repoData.value().repos.length,group:'我的仓库'},{id:'ungrouped',label:'未分类',group:'我的仓库'},...repoData.value().customGroups.map(name=>({id:`group:${name}`,label:name,group:'我的仓库分组'})),{id:'star-all',label:'全部 Star 收藏',count:starData.value().repos.length,group:'Star 收藏'},...starData.value().lists.map(list=>({id:`star-group:${list.name}`,label:list.name,group:'Star 收藏'}))]);
const groups=computed(()=>[...new Set(options.value.map(item=>item.group||''))]);
const selected=computed(()=>options.value.find(item=>item.id===selectedId.value));
const isStarBoard=computed(()=>selectedId.value==='star-all'||selectedId.value.startsWith('star-group:'));
const displayedRepos=computed(()=>{
 const data=isStarBoard.value?starData.value().repos.filter(repo=>selectedId.value==='star-all'||(starData.value().repoListNames.get(repo.full_name.toLowerCase())||[]).includes(selectedId.value.slice('star-group:'.length))).map(repo=>({id:repo.id,fullName:repo.full_name,description:repo.description,language:repo.language,stargazersCount:repo.stargazers_count,badge:'Star',avatar:repo.owner?.avatar_url||'',updatedAt:repo.updated_at,groups:starData.value().repoListNames.get(repo.full_name.toLowerCase())||[],visibility:((repo as GitHubRawRepo & {private?:boolean}).private===true?'private':(repo as GitHubRawRepo & {private?:boolean}).private===false?'public':'unknown') as 'private'|'public'|'unknown'})):repositoriesInBoard(repoData.value().repos,repoData.value().repoGroupsMap,selectedId.value).map(repo=>({id:repo.id,fullName:repo.fullName,description:repo.description,language:repo.language,stargazersCount:repo.stargazersCount,badge:repo.isPrivate?'私有':'公开',avatar:'',updatedAt:repo.updatedAt,groups:repositoryGroups(repo,repoData.value().repoGroupsMap),visibility:(repo.isPrivate?'private':'public') as 'private'|'public'}));
 const q=query.value.trim().toLowerCase();return q?data.filter(repo=>repo.fullName.toLowerCase().includes(q)||(repo.description||'').toLowerCase().includes(q)):data;
});
const displayedVideos=computed(()=>{const q=query.value.trim().toLowerCase();return q?videos.value.filter(video=>video.title.toLowerCase().includes(q)):videos.value;});
function isSelected(kind:ResourceAttachment['kind'],id:string){return props.selectedResources.some(item=>item.kind===kind&&item.id.toLowerCase()===id.toLowerCase());}
function videoResource(video:BiliVideoData):ResourceAttachment|null{if(!/^BV[0-9A-Za-z]{10}$/.test(video.bvid||''))return null;return {kind:'bilibili',id:video.bvid,title:video.title,url:`https://www.bilibili.com/video/${video.bvid}`,author:video.upper?.name,duration:video.duration};}
function repoResource(repo:{fullName:string;description:string|null;language:string|null;visibility:'public'|'private'|'unknown'}):ResourceAttachment|null{if(!/^[a-z0-9-]+\/[a-z0-9_.-]+$/i.test(repo.fullName))return null;return {kind:'github',id:repo.fullName,title:repo.fullName,url:`https://github.com/${repo.fullName}`,description:repo.description||'',language:repo.language,visibility:repo.visibility};}
function select(resource:ResourceAttachment|null){if(resource&&!props.disabled)emit('select',resource);}
function drag(event:DragEvent,resource:ResourceAttachment|null){if(!resource||props.disabled){event.preventDefault();return;}event.dataTransfer?.setData('application/x-tab-project-resource','resource');if(event.dataTransfer)event.dataTransfer.effectAllowed='copy';emit('dragStart',resource);}
function duration(seconds:number){if(!Number.isFinite(seconds)||seconds<=0)return '';const n=Math.floor(seconds);return `${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`;}
function count(value?:number){if(!Number.isFinite(value))return '播放量未知';return Number(value)>=10000?`${(Number(value)/10000).toFixed(1)}万`:String(value);}
function updatedDate(value:string){return /^\d{4}-\d{2}-\d{2}/.test(value||'')?value.slice(0,10):'';}
function coverUrl(value:string){const raw=(value||'').replace(/^http:/,'https:');return raw.startsWith('//')?`https:${raw}`:raw;}
async function loadFolder(id:string,nextPage=1){
 const seq=++generation;selectedId.value=id;if(nextPage===1){videos.value=[];total.value=0;page.value=1;hasMore.value=false;}loading.value=true;error.value='';
 try{const {bilibiliService}=await import('../services/bilibili.service');const data=await bilibiliService.getFolderVideos(id,nextPage,pageSize);if(alive&&seq===generation){videos.value=data.medias.slice(0,pageSize);total.value=data.total;hasMore.value=data.hasMore;page.value=nextPage;}}
 catch(e){if(alive&&seq===generation)error.value=e instanceof Error?e.message:'视频读取失败';}
 finally{if(alive&&seq===generation)loading.value=false;}
}
async function loadFolders(){
 const seq=++generation;loading.value=true;error.value='';warning.value='';videos.value=[];folders.value=[];selectedId.value='';
 try{const {bilibiliService}=await import('../services/bilibili.service');const user=await bilibiliService.getUserNav();if(!alive||seq!==generation)return;if(!user.isLogin||!user.mid)throw new Error('未登录 B 站，请先在 B 站插件中登录。');
 const collectAll=async()=>{const first=await bilibiliService.getCollectedFolders(1,50,user.mid);const list=[...first.list];let partial=false;for(let pn=2;list.length<first.count && pn<=20;pn++){if(!alive||seq!==generation)return {list,partial:true};try{const next=await bilibiliService.getCollectedFolders(pn,50,user.mid);if(!next.list.length){partial=true;break;}list.push(...next.list);}catch{partial=true;break;}}return {list,partial:partial||list.length<first.count};};
 const [created,collected]=await Promise.allSettled([bilibiliService.getCreatedFolders(user.mid),collectAll()]);if(!alive||seq!==generation)return;if(created.status==='rejected'&&collected.status==='rejected')throw new Error('收藏夹读取失败，请检查网络后重试。');if(created.status==='rejected'||collected.status==='rejected'||(collected.status==='fulfilled'&&collected.value.partial))warning.value='部分收藏夹读取失败或数量超过上限，可刷新重试。';folders.value=[...(created.status==='fulfilled'?created.value:[]),...(collected.status==='fulfilled'?collected.value.list:[]),...bilibiliService.getOtherFolders()];const first=folders.value.find(folder=>!folder.isOther)||folders.value[0];if(first){await loadFolder(folderKey(first));return;}}
 catch(e){if(alive&&seq===generation)error.value=e instanceof Error?e.message:'收藏夹读取失败';}finally{if(alive&&seq===generation)loading.value=false;}
}
async function loadOwnRepos(){repoRequest?.abort();const request=new AbortController();repoRequest=request;reposLoading.value=true;reposError.value='';reposWarning.value='';try{const {loadOwnRepositorySnapshot}=await import('./github-resources');const result=await loadOwnRepositorySnapshot(request.signal);if(alive&&repoRequest===request){repoData.value=()=>({...result,loading:false});reposWarning.value=result.warning;}}catch(e){if(alive&&repoRequest===request&&!request.signal.aborted)reposError.value=e instanceof Error?e.message:'仓库读取失败';}finally{if(alive&&repoRequest===request){repoRequest=null;reposLoading.value=false;}}}
async function loadStars(){starRequest?.abort();const request=new AbortController();starRequest=request;starsLoading.value=true;starsError.value='';starsWarning.value='';try{const {loadStarRepositorySnapshot}=await import('./github-resources');const result=await loadStarRepositorySnapshot(request.signal);if(alive&&starRequest===request){starData.value=()=>result;starsWarning.value=result.warning;starsLoaded.value=true;}}catch(e){if(alive&&starRequest===request&&!request.signal.aborted)starsError.value=e instanceof Error?e.message:'Star 收藏读取失败';}finally{if(alive&&starRequest===request){starRequest=null;starsLoading.value=false;}}}
function selectBoard(id:string){query.value='';if(props.kind==='bilibili')void loadFolder(id);else{selectedId.value=id;if((id==='star-all'||id.startsWith('star-group:'))&&!starsLoaded.value&&!starsLoading.value)void loadStars();}}
function onAccountChange(changes:Record<string,unknown>,area:string){if(area!=='local'||(!('ghUser' in changes)&&!('ghToken' in changes)))return;repoRequest?.abort();starRequest?.abort();repoData.value=()=>({repos:[],customGroups:[],repoGroupsMap:{},loading:false});starData.value=()=>({repos:[],lists:[],repoListNames:new Map(),loading:false});starsLoaded.value=false;starsError.value='';selectedId.value='all';void loadOwnRepos();}
onMounted(()=>{if(props.kind==='bilibili'){ready.value=true;void loadFolders();return;}selectedId.value='all';ready.value=true;if(typeof chrome!=='undefined')chrome.storage?.onChanged?.addListener(onAccountChange);void loadOwnRepos();});
onBeforeUnmount(()=>{alive=false;generation++;repoRequest?.abort();starRequest?.abort();repoRequest=null;starRequest=null;if(typeof chrome!=='undefined')chrome.storage?.onChanged?.removeListener(onAccountChange);emit('dragEnd');});
</script>
<template>
  <section class="resource-browser" :aria-label="kind==='bilibili'?'B站收藏夹':'GitHub 仓库'">
    <header class="browser-header"><div><strong>{{ kind==='bilibili'?'B 站收藏夹':'GitHub 仓库' }}</strong><small>点击添加或拖到上方输入框 · 不会自动发送</small></div><div><button type="button" :disabled="loading||reposLoading||starsLoading" @click="kind==='bilibili'?loadFolders():isStarBoard?loadStars():loadOwnRepos()">↻ 刷新</button><button type="button" aria-label="关闭资源浏览" @click="emit('close')">✕</button></div></header>
    <div class="browser-layout"><nav class="browser-folders" aria-label="资源分组"><div v-for="group in groups" :key="group" class="folder-group"><small>{{ group }}</small><button v-for="option in options.filter(item=>item.group===group)" :key="option.id" type="button" :class="{selected:selectedId===option.id}" @click="selectBoard(option.id)"><span class="folder-label">{{ kind==='bilibili'?'▰':'▸' }} &nbsp;{{ option.label }}</span><span v-if="'count' in option && option.count!=null" class="folder-count">{{ option.count }}</span></button></div><p v-if="!options.length && !loading" class="hint">暂无可用分组</p></nav>
      <div class="browser-content"><div class="browser-toolbar"><strong>{{ selected?.label||'选择分组' }}</strong><input v-model="query" type="search" :placeholder="kind==='bilibili'?'搜索当前页视频':'搜索仓库'" aria-label="筛选已加载资源" /></div><p v-if="!ready || (loading && !videos.length) || (kind==='github' && (isStarBoard?starsLoading:reposLoading) && !displayedRepos.length)" class="hint">正在读取…</p><p v-if="error" class="error" role="alert">{{ error }} <button type="button" @click="loadFolders">重试</button></p><p v-if="warning" class="hint">{{ warning }}</p><p v-if="kind==='github' && !isStarBoard && reposError" class="error" role="alert">{{ reposError }} <button type="button" @click="loadOwnRepos">重试</button></p><p v-if="kind==='github' && !isStarBoard && reposWarning" class="hint">{{ reposWarning }}</p><p v-if="kind==='github' && isStarBoard && starsError" class="error" role="alert">{{ starsError }} <button type="button" @click="loadStars">重试</button></p><p v-if="kind==='github' && isStarBoard && starsWarning" class="hint">{{ starsWarning }}</p>
        <template v-if="ready && kind==='bilibili'"><p v-if="!loading&&!error&&!displayedVideos.length" class="hint">{{ query?'当前页没有匹配视频。':'该收藏夹暂无视频。' }}</p><div class="video-grid"><article v-for="video in displayedVideos" :key="`${video.bvid}-${video.id}`" class="video-card" :draggable="!disabled && Boolean(videoResource(video))" @dragstart="drag($event,videoResource(video))" @dragend="emit('dragEnd')"><button type="button" class="cover" :disabled="disabled || !videoResource(video)" :aria-label="`${isSelected('bilibili',video.bvid)?'移除':'添加'} ${video.title}`" :aria-pressed="isSelected('bilibili',video.bvid)" @click="select(videoResource(video))"><img v-if="video.cover" :src="coverUrl(video.cover)" alt="" loading="lazy" referrerpolicy="no-referrer" /><span v-else class="cover-placeholder">▶</span><span class="cover-action" :class="{ selected:isSelected('bilibili',video.bvid) }">{{ isSelected('bilibili',video.bvid)?'✓ 已添加':'＋ 添加' }}</span><span v-if="duration(video.duration)" class="duration">{{ duration(video.duration) }}</span></button><strong>{{ video.title }}</strong><small>{{ video.upper?.name||'UP 主未知' }} · ▶ {{ count(video.cnt_info?.play) }}</small></article></div><div v-if="page>1 || hasMore" class="resource-pager"><button type="button" :disabled="loading || page<=1" @click="loadFolder(selectedId,page-1)">‹ 上一页</button><span>{{ page }} / {{ totalPages }}</span><button type="button" :disabled="loading || !hasMore" @click="loadFolder(selectedId,page+1)">下一页 ›</button></div></template>
        <template v-else-if="ready && kind==='github'"><p v-if="isStarBoard&&starsLoaded&&!starsLoading&&!starsError&&!displayedRepos.length" class="hint">{{ starData().repos.length ? '该分组暂无匹配仓库。' : '暂无 Star 收藏。' }}</p><p v-else-if="!isStarBoard&&!reposLoading&&!reposError&&!displayedRepos.length" class="hint">该分组暂无匹配仓库。</p><div class="repo-grid"><button v-for="repo in displayedRepos" :key="repo.id" type="button" class="repo-card" :class="{ 'is-selected':isSelected('github',repo.fullName) }" :disabled="disabled || !repoResource(repo)" :aria-pressed="isSelected('github',repo.fullName)" :aria-label="`${isSelected('github',repo.fullName)?'移除':'添加'} ${repo.fullName}`" :draggable="!disabled && Boolean(repoResource(repo))" @click="select(repoResource(repo))" @dragstart="drag($event,repoResource(repo))" @dragend="emit('dragEnd')"><div class="repo-title"><img v-if="repo.avatar" class="repo-avatar" :src="repo.avatar" alt="" loading="lazy" referrerpolicy="no-referrer" /><span v-else class="repo-avatar repo-avatar-fallback">{{ repo.fullName.charAt(0).toUpperCase() }}</span><strong><span>{{ repo.fullName.split('/')[0] }}/</span>{{ repo.fullName.split('/').slice(1).join('/') }}</strong><span class="repo-add">{{ isSelected('github',repo.fullName)?'✓':'＋' }}</span></div><div class="repo-badges"><span v-for="group in repo.groups.slice(0,2)" :key="group" class="repo-group">▣ {{ group }}</span><span v-if="!repo.groups.length" class="repo-visibility">{{ repo.badge }}</span><span v-if="repo.groups.length>2" class="repo-visibility">+{{ repo.groups.length-2 }}</span></div><p>{{ repo.description||'暂无描述' }}</p><div class="repo-meta"><span>★ {{ repo.stargazersCount }}</span><span v-if="repo.language">{{ repo.language }}</span><span v-if="updatedDate(repo.updatedAt)">更新 {{ updatedDate(repo.updatedAt) }}</span></div></button></div></template>
      </div>
    </div><footer>添加后仅放入草稿；视频字幕或仓库 README 需手动读取并确认附带。</footer>
  </section>
</template>
<style scoped>
.resource-browser{flex:1;min-height:260px;display:flex;flex-direction:column;overflow:hidden;border:1px solid var(--border,#e2e8f0);border-radius:12px;background:var(--panel,#fff);color:var(--text,#26334b)}.browser-header{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:12px 16px;border-bottom:1px solid var(--border,#e2e8f0)}.browser-header strong,.browser-header small{display:block}.browser-header strong{font-size:13px}.browser-header small{margin-top:3px;color:var(--muted,#94a3b8);font-size:10px}.browser-header button,.load-more button{margin-left:5px;border:1px solid var(--border,#e2e8f0);border-radius:7px;padding:5px 9px;background:var(--surface,#f8fafc);color:var(--text,#334155);cursor:pointer;font:inherit;font-size:11px}.browser-layout{display:grid;grid-template-columns:190px minmax(0,1fr);flex:1;min-height:0}.browser-folders{overflow:auto;padding:12px 8px;border-right:1px solid var(--border,#e2e8f0)}.folder-group{margin-bottom:16px}.folder-group>small{display:block;padding:4px 8px;color:var(--muted,#94a3b8);font-size:10px}.folder-group button{display:flex;align-items:center;justify-content:space-between;gap:5px;width:100%;padding:9px 8px;border:0;border-radius:7px;background:transparent;color:var(--text,#334155);text-align:left;cursor:pointer;font:inherit;font-size:11px}.folder-group button:hover{background:var(--surface,#f1f5f9)}.folder-group button.selected{background:rgba(0,174,236,.13);color:#0089bf}.folder-label{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.folder-count{color:var(--muted,#94a3b8);font-size:10px}.browser-content{min-width:0;overflow:auto;padding:14px}.browser-toolbar{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px}.browser-toolbar strong{font-size:12px}.browser-toolbar input{width:min(220px,50%);padding:7px 9px;border:1px solid var(--border,#e2e8f0);border-radius:7px;background:var(--surface,#f8fafc);color:var(--text,#334155);font:inherit;font-size:11px}.video-grid,.repo-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,165px),1fr));gap:12px}.video-card,.repo-card{min-width:0;cursor:grab}.video-card strong{display:-webkit-box;overflow:hidden;-webkit-line-clamp:2;-webkit-box-orient:vertical;margin-top:7px;font-size:11px;line-height:1.45}.video-card small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-top:5px;color:var(--muted,#94a3b8);font-size:10px}.cover{position:relative;aspect-ratio:16/10;overflow:hidden;border-radius:7px;background:var(--surface,#f1f5f9)}.cover img{width:100%;height:100%;object-fit:cover}.cover-placeholder{position:absolute;inset:0;display:grid;place-items:center;color:#d994b4}.duration{position:absolute;bottom:5px;right:5px;padding:2px 4px;border-radius:3px;background:#000a;color:#fff;font-size:10px}.video-card button,.repo-card button{margin-top:7px;border:1px solid var(--border,#e2e8f0);border-radius:6px;background:var(--surface,#f8fafc);color:var(--text,#334155);padding:5px 8px;font:inherit;font-size:10px;cursor:pointer}.repo-card{display:flex;flex-direction:column;min-height:155px;padding:12px;border:1px solid var(--border,#e2e8f0);border-radius:9px;background:var(--surface,#f8fafc)}.repo-title{display:flex;justify-content:space-between;gap:5px}.repo-title strong{min-width:0;overflow-wrap:anywhere;font-size:11px}.repo-title small{flex:none;color:var(--muted,#94a3b8);font-size:9px}.repo-card p{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;color:var(--muted,#64748b);font-size:10px;line-height:1.5}.repo-meta{margin-top:auto;color:var(--muted,#94a3b8);font-size:10px}.repo-card button{align-self:flex-start}.hint,.error{color:var(--muted,#94a3b8);font-size:11px;line-height:1.5}.error{color:#b45309}.error button{border:0;background:none;color:#7569ec;cursor:pointer}.load-more{text-align:center;margin:14px}footer{padding:8px 14px;border-top:1px solid var(--border,#e2e8f0);color:var(--muted,#94a3b8);font-size:10px}@media(max-width:760px){.browser-layout{grid-template-columns:130px minmax(0,1fr)}.browser-header small{display:none}}
